<?php
namespace App\Services;
use App\Models\Lease;use App\Models\Receivable;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class LeaseActivationService {public function activate(Lease $lease,int $actorId):Lease{return DB::transaction(function()use($lease,$actorId){$lease=Lease::query()->lockForUpdate()->findOrFail($lease->id);if($lease->status!=='draft')abort(409,'لا يمكن تفعيل هذا العقد بحالته الحالية.');$spaces=DB::table('lease_spaces')->where('lease_id',$lease->id)->lockForUpdate()->get();foreach($spaces as $space){$overlap=DB::table('lease_spaces')->join('leases','leases.id','=','lease_spaces.lease_id')->where('lease_spaces.property_space_id',$space->property_space_id)->where('leases.status','active')->where('leases.id','<>',$lease->id)->where('lease_spaces.start_date','<=',$space->end_date)->where('lease_spaces.end_date','>=',$space->start_date)->lockForUpdate()->exists();if($overlap)abort(409,'توجد فترة إيجار متداخلة لهذه المساحة.');}$installments=$lease->installments()->lockForUpdate()->get();if($installments->isEmpty()||$installments->sum('original_amount')!=$lease->total_value)abort(422,'الأقساط لا تطابق قيمة العقد.');foreach($installments as $item){Receivable::firstOrCreate(['installment_id'=>$item->id],['id'=>(string)Str::uuid(),'organization_id'=>$lease->organization_id,'tenant_id'=>$lease->tenant_id,'due_date'=>$item->due_date,'original_amount'=>$item->original_amount]);}$lease->status='active';$lease->version++;$lease->save();AuditService::record($lease->organization_id,$actorId,'lease.activated','lease',$lease->id,null,['status'=>'active']);return $lease;});}}
